const input = $json;
const tender = input.tender;
const request = $('Проверить вход Orchestrator').item.json;

if (!tender) {
  throw new Error('TenderPlan response does not contain "tender"');
}

const requestedTenderId = request.tender_id;
const responseTenderId = typeof tender._id === 'string' ? tender._id.trim() : '';

if (!responseTenderId) {
  throw new Error('[Orchestrator FullInfo] TenderPlan response tender._id is required.');
}
if (responseTenderId !== requestedTenderId) {
  throw new Error('[Orchestrator FullInfo] TenderPlan response identity mismatch.');
}

// TenderPlan отдаёт даты как Unix timestamp в миллисекундах.
// Переводим их в нормальный ISO-формат.
function toIso(timestamp) {
  if (timestamp === null || timestamp === undefined) {
    return null;
  }

  const date = new Date(timestamp);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString();
}

// Определяем расширение только из реального имени файла.
// Ничего не додумываем.
function getExtension(fileName) {
  if (!fileName || typeof fileName !== 'string') {
    return null;
  }

  const lastDot = fileName.lastIndexOf('.');

  if (lastDot === -1 || lastDot === fileName.length - 1) {
    return null;
  }

  return fileName.slice(lastDot + 1).toLowerCase();
}


// ----------------------------------------------------
// 1. ДОКУМЕНТЫ
// ----------------------------------------------------

const attachments = Array.isArray(tender.attachments)
  ? tender.attachments.map((file, index) => ({
      document_index: index + 1,

      // Оригинальное имя файла из TenderPlan
      file_name: file.realName ?? null,

      // Расширение пригодится в следующем блоке
      file_extension: getExtension(file.realName),

      // Категория / отображаемое название TenderPlan
      display_name: file.displayName ?? null,

      // Прямая ссылка на скачивание
      download_url: file.href ?? null,

      // Дата публикации документа
      publication_at: toIso(file.publicationDateTime),

      // TenderPlan в твоём примере возвращает null,
      // но поле сохраняем
      source_size: file.size ?? null,
    }))
  : [];


// ----------------------------------------------------
// 2. ЗАКАЗЧИКИ
// ----------------------------------------------------

// Не ограничиваемся первым заказчиком.
// В некоторых закупках их потенциально может быть несколько.
const customers = Array.isArray(tender.customers)
  ? tender.customers.map(customer => ({
      id: customer.guid ?? null,
      name: customer.name ?? null,
      region: customer.region ?? null,
    }))
  : [];


// ----------------------------------------------------
// 3. НОРМАЛИЗОВАННАЯ КАРТОЧКА ТЕНДЕРА
// ----------------------------------------------------

const tenderMeta = {
  // Источник данных
  source: request.source,

  // Идентификаторы TenderPlan / закупки
  tender_id: requestedTenderId,
  tender_number: tender.number ?? null,
  tender_external_id: tender.id ?? null,
  eid: tender.eid ?? null,

  // Основная информация
  title: tender.orderName ?? null,
  max_price: tender.maxPrice ?? null,

  // Не подставляем RUB самостоятельно.
  // Если TenderPlan не сообщил валюту — оставляем null.
  currency: tender.currency ?? null,

  region: tender.region ?? null,
  status: tender.status ?? null,
  kind: tender.kind ?? null,
  type: tender.type ?? null,
  placing_way: tender.placingWay ?? null,

  // Даты
  publication_at: toIso(tender.publicationDateTime),
  receive_at: toIso(tender.receiveDateTime),
  submission_start_at: toIso(tender.submissionStartDateTime),
  submission_close_at: toIso(tender.submissionCloseDateTime),
  scoring_at: toIso(tender.scoringDateTime),
  summing_up_at: toIso(tender.summingUpDateTime),
  updated_at_source: toIso(tender.updateDateTime),

  // Заказчики
  customers,

  // Для удобства отдельно первый заказчик.
  // Это не означает, что остальных мы теряем.
  primary_customer: customers[0] ?? null,

  // Площадка
  platform: {
    name: tender.platform?.name ?? null,
    url: tender.platform?.href ?? null,
  },

  // Ссылка непосредственно на закупку на ЭТП
  tender_url: tender.href ?? null,

  // Финансовые / обеспечительные данные,
  // которые TenderPlan уже отдаёт структурированно
  prepayment: tender.prepayment ?? null,
  guarantee_application: tender.guaranteeApp ?? null,
  guarantee_contract: tender.guaranteeContract ?? null,
  guarantee_provision: tender.guaranteeProv ?? null,

  // Классификаторы
  okpd2: Array.isArray(tender.okpd2) ? tender.okpd2 : [],
  okpd: Array.isArray(tender.okpd) ? tender.okpd : [],
  ktru: Array.isArray(tender.ktru) ? tender.ktru : [],

  // Дополнительные признаки
  smp: tender.smp ?? null,
  multilot: tender.multilot ?? null,
  is_changed: tender.isChanged ?? null,
  is_deleted: tender.isDeleted ?? null,

  // Полный ответ TenderPlan сохраняется без преобразования как отдельный
  // аудируемый источник для агентского анализа.
  source_payload: input,

  // Количество документов
  documents_count: attachments.length,
};


// ----------------------------------------------------
// 4. РЕЗУЛЬТАТ
// ----------------------------------------------------

return {
  json: {
    source: request.source,
    source_event_key: request.source_event_key,
    trigger_kind: request.trigger_kind,

    // Нормализованная информация,
    // которую удобно использовать во всём workflow
    tender_meta: tenderMeta,

    // Документы. Следующая Split Out работает именно с этим массивом.
    attachments,

    // ВАЖНО:
    // сохраняем полный оригинальный ответ TenderPlan вообще без изменений.
    // Если позже обнаружим полезное поле — оно не потеряно.
    raw_source: input,
  },
};

const tenderId = typeof $json.tender_id === 'string' ? $json.tender_id.trim() : '';
const source = typeof $json.source === 'string' ? $json.source.trim().toLowerCase() : '';
const sourceEventKey = typeof $json.source_event_key === 'string' ? $json.source_event_key.trim() : '';
const triggerKind = typeof $json.trigger_kind === 'string' ? $json.trigger_kind.trim() : '';

if (!tenderId || tenderId.length > 128) {
  throw new Error('[Orchestrator input] tender_id must be a non-empty string up to 128 characters.');
}
if (!source || source.length > 64 || source !== 'tenderplan') {
  throw new Error('[Orchestrator input] source must be tenderplan.');
}
if (!sourceEventKey || sourceEventKey.length > 512) {
  throw new Error('[Orchestrator input] source_event_key must be a non-empty string up to 512 characters.');
}
const allowedTriggerKinds = new Set(['tenderplan_mark', 'recovery_scan', 'manual']);
if (!triggerKind || triggerKind.length > 64 || !allowedTriggerKinds.has(triggerKind)) {
  throw new Error('[Orchestrator input] trigger_kind is invalid.');
}

return {
  json: {
    tender_id: tenderId,
    source,
    source_event_key: sourceEventKey,
    trigger_kind: triggerKind,
  },
};

const items = $input.all();
if (items.length !== 1) {
  throw new Error(`[Orchestrator conflict] Expected exactly one unfinished run, received ${items.length}.`);
}

const row = items[0]?.json ?? {};
const request = $('Создать запуск и зарегистрировать документы').item.json;

if (!row.analysis_run_id || !row.source || !row.tender_id || !row.status) {
  throw new Error('[Orchestrator conflict] Unfinished run was not found after insert conflict.');
}
if (['completed', 'superseded'].includes(row.status)) {
  throw new Error('[Orchestrator conflict] Terminal run cannot own an active-run conflict.');
}
if (row.source !== request.source || row.tender_id !== request.tender_id) {
  throw new Error('[Orchestrator conflict] Loaded run identity does not match the conflict sentinel.');
}

return [{
  json: {
    ...row,
    created_new_run: false,
    action: 'concurrent_existing_run',
  },
}];

const request = $('Проверить вход Orchestrator').first().json;
const createdRow = $('Создать запуск и зарегистрировать документы').first().json;
const inputRow = $input.first()?.json ?? {};
const createdNewRun = inputRow.created_new_run === true;
const row = createdNewRun ? createdRow : inputRow;

if (!row.analysis_run_id || !row.status) {
  throw new Error('[Orchestrator result] analysis_run_id and status are required.');
}
if (row.source !== request.source || row.tender_id !== request.tender_id) {
  throw new Error('[Orchestrator result] Run identity does not match validated input.');
}

const supportedExtensions = new Set(['pdf', 'docx', 'xlsx', 'xls']);
const documentsDispatched = createdNewRun && Array.isArray(createdRow.attachments)
  ? createdRow.attachments.filter((attachment) =>
      attachment?.status === 'pending'
      && supportedExtensions.has(String(attachment?.file_extension ?? '').trim().toLowerCase()),
    ).length
  : 0;
const action = createdNewRun ? 'created_new_run' : 'concurrent_existing_run';
const agenticShadow = inputRow.agentic_shadow ?? {
  schema_version: 'tender_agentic_dispatch_v1',
  attempted: false,
  dispatched: false,
  acknowledged: false,
  no_op: false,
  success: null,
  job_id: null,
  status: null,
  outcome: null,
  action: null,
  error_code: null,
  reason: createdNewRun ? 'no_processable_documents' : 'concurrent_existing_run'
};
return [{
  json: {
    success: true,
    analysis_run_id: row.analysis_run_id,
    source: request.source,
    tender_id: request.tender_id,
    source_event_key: request.source_event_key,
    trigger_kind: request.trigger_kind,
    created_new_run: createdNewRun,
    action,
    status: row.status,
    next_state: row.status,
    documents_total: Number(row.documents_total ?? 0),
    registered_documents_count: Number(row.registered_documents_count ?? row.documents_total ?? 0),
    documents_dispatched: documentsDispatched,
    agentic_shadow: agenticShadow
  },
}];

const preparation = $input.first()?.json ?? {};
const normalized = $('нормализовать карточку').first().json;
const expectedRunId = String($('Сформировать analysis_run_id').first().json.analysis_run_id ?? '').trim();
const schemaVersion = 'tender_document_ingestion_v1';
const supportedExtensions = new Set(['pdf', 'docx', 'xlsx', 'xls']);
const sha256Pattern = /^[0-9a-f]{64}$/iu;

function fail(message) {
  const safeMessage = String(message ?? 'unknown preparation failure').slice(0, 500);
  throw new Error('[Orchestrator preparation] ' + safeMessage);
}

if (preparation.success !== true) {
  const failure = preparation.failure ?? {};
  fail(String(failure.error_code ?? 'DOCUMENT_PREPARATION_FAILED') + ': ' + String(failure.error_message ?? 'Document Preparation failed'));
}
if (preparation.schema_version !== schemaVersion) {
  fail('INGESTION_CONTRACT_INVALID: unexpected schema_version');
}
if (String(preparation.analysis_run_id ?? '').trim() !== expectedRunId) {
  fail('INGESTION_CONTRACT_INVALID: analysis_run_id mismatch');
}
const manifest = preparation.manifest;
if (!manifest || manifest.schema_version !== schemaVersion || String(manifest.analysis_run_id ?? '').trim() !== expectedRunId) {
  fail('INGESTION_CONTRACT_INVALID: manifest identity is invalid');
}
if (!Array.isArray(manifest.documents)) {
  fail('INGESTION_CONTRACT_INVALID: manifest.documents must be an array');
}
if (
  Number(manifest.registered_document_count) !== manifest.documents.length
  || Number(manifest.source_attachment_count) !== normalized.attachments.length
) {
  fail('INGESTION_CONTRACT_INVALID: manifest counts are inconsistent');
}

let processableCount = 0;
let skippedCount = 0;
for (const [offset, document] of manifest.documents.entries()) {
  if (Number(document?.document_index) !== offset + 1) {
    fail('INGESTION_CONTRACT_INVALID: document_index sequence is invalid');
  }
  if (!['pending', 'skipped'].includes(document?.status)) {
    fail('INGESTION_CONTRACT_INVALID: document status is invalid');
  }
  if (document.status === 'skipped') {
    skippedCount += 1;
    continue;
  }
  processableCount += 1;
  if (
    !supportedExtensions.has(String(document.file_extension ?? '').trim().toLowerCase())
    || typeof document.file_name !== 'string'
    || !document.file_name.trim()
    || typeof document.mime_type !== 'string'
    || !document.mime_type.trim()
    || !Number.isSafeInteger(document.file_size)
    || document.file_size < 0
    || !sha256Pattern.test(String(document.ingestion_metadata?.content_sha256 ?? ''))
  ) {
    fail('INGESTION_CONTRACT_INVALID: processable document identity is incomplete');
  }
}
if (
  processableCount < 1
  || Number(manifest.processable_document_count) !== processableCount
  || Number(manifest.skipped_document_count) !== skippedCount
) {
  fail('INGESTION_CONTRACT_INVALID: manifest status counts are inconsistent');
}

return [{ json: {
  ...normalized,
  analysis_run_id: expectedRunId,
  attachments: manifest.documents,
  manifest,
} }];

const dispatch = $input.first()?.json ?? {};
const context = $('Создать запуск и зарегистрировать документы').first().json;
const request = $('Проверить вход Orchestrator').first().json;

if (dispatch.schema_version !== 'tender_agentic_dispatch_v1') {
  throw new Error('[Orchestrator agentic shadow] Unexpected Dispatch contract.');
}
if (!context.analysis_run_id || context.analysis_run_id !== $('Создан новый запуск?').first().json.analysis_run_id) {
  throw new Error('[Orchestrator agentic shadow] analysis_run_id context mismatch.');
}

const status = typeof dispatch.status === 'string' ? dispatch.status : null;
const outcome = typeof dispatch.outcome === 'string' ? dispatch.outcome : null;
const action = typeof dispatch.action === 'string' ? dispatch.action : null;
const noOp = dispatch.no_op === true;
const success = dispatch.success === false ? false : true;
const acknowledged = success && (noOp || ['ready', 'running', 'validating', 'completed'].includes(status));

return [{
  json: {
    ...context,
    source_event_key: request.source_event_key,
    agentic_shadow: {
      schema_version: 'tender_agentic_dispatch_v1',
      attempted: true,
      dispatched: !noOp && status === 'running',
      acknowledged,
      no_op: noOp,
      success,
      job_id: typeof dispatch.job_id === 'string' ? dispatch.job_id : null,
      status,
      outcome,
      action,
      error_code: typeof dispatch.error_code === 'string' ? dispatch.error_code : null
    }
  }
}];
